const API = "http://127.0.0.1:8000/api";

export const createOrder = async (order) => {
  return fetch(`${API}/orders/create/`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(order),
  });
};
